        const direct={"runtime-audit":"source_integrated_runtime_audit_outcome","checkpoint-disposition":"source_checkpoint_disposition_outcome","checkpoint-build":"source_checkpoint_build_outcome","checkpoint-save":"source_checkpoint_save_outcome","checkpoint-publish":"source_checkpoint_publish_outcome","weather-preflight-state-build":"source_weather_preflight_state_build_outcome","weather-preflight-state-save":"source_weather_preflight_state_save_outcome","private-runtime-bundle-spec":"source_private_runtime_bundle_spec_outcome","private-runtime-bundle-create":"source_private_runtime_bundle_create_outcome","private-runtime-write-authority":"source_private_runtime_write_authority_outcome","private-runtime-publish":"source_private_runtime_publish_outcome"};
        for(const [id,key]of Object.entries(direct)){
