jobs:
  source-route-request:
    name: Validate the explicit SOURCE request before any operational reentry
    runs-on: ubuntu-24.04
    timeout-minutes: 2
    permissions:
      contents: read
    steps:
      - name: Reject unknown or mixed SOURCE request before any operational reentry
        id: source-route-request
        shell: bash
        env:
          SOURCE_REQUEST: ${{ toJSON(inputs) }}
        run: |
          set -euo pipefail
          node --input-type=module <<'NODE'
          import fs from 'node:fs';
          import assert from 'node:assert/strict';
          const request=JSON.parse(process.env.SOURCE_REQUEST);
          assert(request && typeof request==='object' && !Array.isArray(request),'SOURCE_ROUTE_REQUEST_INVALID');
          const booleans=["current_family_cold_start","completed_private_runtime","quick_confirmation","weather_state_epoch_bootstrap","weather_state_epoch_checkpoint_reentry","native_sampling_identity_original_recovery"], strings=["completed_stage_source","quick_progress_source","checkpoint_target_hour","weather_state_epoch_archive_key","weather_state_epoch_archive_catalog_sha256","weather_state_epoch_raw_cache_key"];
          const known=new Set(['source_normal_producer',...booleans,...strings]);
          assert(Object.keys(request).every(key=>known.has(key)),'SOURCE_ROUTE_REQUEST_UNKNOWN');
          assert.equal(typeof request.source_normal_producer,'boolean','SOURCE_ROUTE_SELECTION_UNKNOWN');
          if(request.source_normal_producer===true){
            for(const key of booleans)assert.equal(request[key],false,'SOURCE_ROUTE_MIXED_BOOLEAN');
            for(const key of strings)assert.equal(request[key],'','SOURCE_ROUTE_MIXED_LOCATOR');
          }
          fs.appendFileSync(process.env.GITHUB_OUTPUT,'route='+(request.source_normal_producer===true?'source':'legacy')+'\n');
          NODE

  operational-recovery-gate:
    needs: source-route-request
    if: needs.source-route-request.result == 'success' && (inputs.current_family_cold_start != true)
    name: Finish an interrupted generation before new work
    permissions:
      contents: read
